WITH base AS (SELECT *, LAST_DAY(shipped_date) AS shipped_date_month_end, COALESCE(carrier, 'NONE') AS resolved_carrier FROM shipments WHERE shipped_date > DATE '2023-11-13' AND carrier IS NOT NULL) SELECT DATE_TRUNC('WEEK', shipped_date) AS week_start, DATE_TRUNC('MONTH', shipped_date_month_end) AS activity_month, APPROX_PERCENTILE(cost, 0.5) AS cost_p50, MAX(cost) FILTER (WHERE carrier = 'Kerry') AS kerry_max_cost, COUNT_IF(status = 'DELIVERED') AS delivered_events, COUNT_IF(status = 'LOST') AS lost_events, ROUND(AVG(cost), 2) AS avg_cost, ROUND(AVG(cost), 2) AS avg_cost_2 FROM base GROUP BY DATE_TRUNC('WEEK', shipped_date), DATE_TRUNC('MONTH', shipped_date_month_end) HAVING COUNT_IF(status = 'DELIVERED') > 1 ORDER BY cost_p50 NULLS LAST;
